RULES = [
    {'priority': 100, 'port': 443, 'source': '*', 'action': 'Allow'},
    {'priority': 200, 'port': 22, 'source': '10.0.0.0/8', 'action': 'Allow'},
    {'priority': 300, 'port': '*', 'source': '*', 'action': 'Deny'},
]
PACKETS = [
    (443, '203.0.113.5'),
    (22, '10.1.2.3'),
    (22, '203.0.113.5'),
    (8080, '10.1.2.3'),
]

def matches_source(rule_source, ip):
    if rule_source == '*':
        return True
    if rule_source == '10.0.0.0/8':
        return ip.startswith('10.')
    return ip == rule_source

def evaluate(port, source_ip):
    for rule in sorted(RULES, key=lambda r: r['priority']):
        if (rule['port'] == '*' or rule['port'] == port) and matches_source(rule['source'], source_ip):
            return (rule['action'], rule['priority'])
    return ('Deny', None)

for port, ip in PACKETS:
    action, priority = evaluate(port, ip)
    print(f'{port} from {ip} -> {action} (rule {priority})')
